# Let me test for backdoor triggers by crafting images with potential triggers
# in different corners and seeing which class gets activated

import torch

def create_test_image_with_patch(patch_type="white", corner="top_left", patch_size=3):
    """Create a clean image with a patch in a specific corner."""
    # Start with a clean image (first clean image)
    img = x_clean[0:1].clone().float() / 255.0  # (1, 3, 32, 32)

    # Denormalize to [0,1] for patch application
    mean = torch.tensor([0.4914, 0.4822, 0.4465]).view(1, 3, 1, 1)
    std = torch.tensor([0.2470, 0.2435, 0.2616]).view(1, 3, 1, 1)
    img_denorm = img * std + mean

    # Apply patch 1 pixel in from corner
    if corner == "top_left":
        y_start, x_start = 1, 1
    elif corner == "top_right":
        y_start, x_start = 1, 32 - 1 - patch_size
    elif corner == "bottom_left":
        y_start, x_start = 32 - 1 - patch_size, 1
    elif corner == "bottom_right":
        y_start, x_start = 32 - 1 - patch_size, 32 - 1 - patch_size

    if patch_type == "white":
        patch = torch.ones(3, patch_size, patch_size)
    elif patch_type == "checkerboard":
        patch = torch.zeros(3, patch_size, patch_size)
        for i in range(patch_size):
            for j in range(patch_size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 1.0
    elif patch_type == "random":
        patch = torch.randint(0, 2, (3, patch_size, patch_size)).float()

    img_denorm[:, :, y_start:y_start+patch_size, x_start:x_start+patch_size] = patch

    # Renormalize
    img_norm = (img_denorm - mean) / std
    # Convert back to uint8
    img_uint8 = (img_norm * std + mean).clamp(0, 1) * 255
    return img_uint8.byte()

